// Package tenantevents provides a Kafka consumer module for tenant lifecycle events.
// It handles tenant migrations on create/update and deferred cleanup on delete.
package fxconfig

import (
	commons_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer"
	fx_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer/fxconfig"
	"github.com/Sokol111/ecommerce-tenant-service-api/pkg/consumer"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

const tenantEventsConsumer = "tenant-events"

// NewKafkaConsumerModule registers a Kafka consumer for tenant events that runs
// database migrations when tenants are created/updated and schedules deferred cleanup on delete.
//
// Requires tenant.NewModule() to be registered in the fx container for Registry and MigrationRunner.
// To add service-specific cleanup, register additional tenant.Cleaner implementations
// in the "tenant_cleaners" fx group:
//
//	fx.Provide(fx.Annotate(s3.NewImageTenantCleaner,
//	    fx.ResultTags(`group:"tenant_cleaners"`),
//	))
func NewKafkaConsumerModule() fx.Option {
	return fx.Options(
		fx.Provide(consumer.NewTenantEventHandler),
		fx_consumer.RegisterHandlerAndConsumer(tenantEventsConsumer, newTenantRouter),
	)
}

func newTenantRouter(h *consumer.TenantEventHandler, log *zap.Logger) commons_consumer.Handler {
	r := commons_consumer.NewRouter(log)
	commons_consumer.Register(r, h.HandleTenantUpdated)
	commons_consumer.Register(r, h.HandleTenantDeleted)
	return r
}

